"""Add web-push curriculum, project, and decisions quiz as local drafts."""
import copy
import datetime
import html
import json
import re
import subprocess
import uuid
from pathlib import Path

root = Path(__file__).resolve().parents[1]
fixture = root / 'src/data/fixtures.json'
entries = json.loads(fixture.read_text())
by_path = {entry['path']: entry for entry in entries}
stamp = datetime.datetime.now(datetime.UTC).isoformat()

def p(value):
    return '<p>' + html.escape(value) + '</p>'

def link(path):
    title = by_path[path]['title'] if path in by_path else next((item['title'] for item in lessons if item['path'] == path), None)
    assert title is not None, path
    return '<a href="/' + html.escape(path, quote=True) + '">' + html.escape(title) + '</a>'

hub = dict(path='web-tech/web-push-and-notification-delivery', title='Web Push and Notification Delivery', summary='Make opt-in alerts useful, private, revocable, and honest about delivery limits.', overview='Web push can alert a person after the page closes, but it is a separate delivery channel with browser permission, a service worker, a subscription endpoint, a push service, and server-side policy. None of those layers guarantees that the person read an alert. This track follows urgent case assignments for field reviewers. It covers when to ask, how to bind subscriptions to accounts, what may appear on a lock screen, and how to recover when a device or push service does not deliver.', bridges=['web-tech/browser-capabilities-and-permission-lifecycle','web-tech/media-and-live-updates','web-tech/privacy-aware-external-integrations'])

lessons = [
    dict(path='web-tech/notification-opt-in-and-channel-preference', title='Notification Opt-In and Channel Preference', summary='Ask for alert permission only after a relevant action and keep a usable in-app path after denial.',
    definition='A browser notification is an interruption outside the current page. Browser permission is required, but permission alone is not a product preference for every alert category. Ask after the person chooses a clear, time-sensitive use case and explain what will arrive. Store a separate, current application preference for assignment alerts, quiet periods, and device scope as needed by the product. A denied, dismissed, or unsupported browser path must leave an in-app inbox or other authorized route to the same work. Do not request a prompt on first load just because the API is available.',
    case='Reviewer 29 receives case assignments across several districts. The case-review app offers Notify me about urgent assignments after the reviewer opens notification settings, not while they are reading an ordinary report. The screen explains that the alert will contain a generic assignment message and a link requiring sign-in. If browser permission is denied, the reviewer can still inspect the in-app assignment inbox and a visible count. Changing the product preference to Off stops future sends even if browser permission stays Granted. An old permission grant is not a reason to restart alerts silently.',
    implementation='Separate browser permission state, product opt-in, and active subscription state in the data model. Only call the browser permission request from an intentional user action, and handle granted, denied, default, and API absence without assuming one browser prompt behavior. Register and subscribe only after current product consent and permission requirements are met. On opt-out, mark the server preference Off first, stop scheduling sends, then remove or invalidate device subscriptions with retry if the browser is unavailable. The in-app inbox remains the authoritative list of assignments, subject to current server authorization.',
    cost='Reading local state is O(1), but repeated permission prompts cost trust and cannot be forced after denial. Keeping a subscription per device adds O(d) stored records for d devices and requires a cleanup path. An in-app inbox adds persistence and query cost, yet it supplies the durable result that a transient notification cannot. Measure the proportion of users who complete setup, the time from opt-out to no further sends, and whether denied users can still find urgent work. Do not optimize only for prompt acceptance.',
    failure='The app requests notification access before showing any case. Many reviewers deny it, and the app then hides assignment counts as if alerts were the only route to work. Restore the inbox and move the request behind settings. Another defect reads Notification.permission as Granted and sends marketing-style alerts despite the product toggle being Off. Require both states before scheduling. Open two devices, disable the category on one, and verify the server policy reaches both. Test a suspended tab, a revoked browser permission, and a browser without the push feature.',
    drill='Start with browser permission Default, product preference Off, and no subscription. Enable urgent alerts through the settings action, then test Granted, Denied, and dismissed outcomes. Disable the category while a job is queued; verify the send decision rechecks the current preference. Leave one device offline during opt-out and inspect its later subscription cleanup. Confirm that the in-app inbox contains the same assignments under current authorization whether or not push is enabled.',
    decision='Treat browser permission as one technical gate, and product opt-in as the continuing decision about which alerts to send.',
    code='function mayScheduleAlert(settings, browserState) {\n  return settings.urgentAssignments === true && browserState === "granted";\n}\nconsole.log(mayScheduleAlert({ urgentAssignments: false }, "granted"));\n// Output: false',
    checks=['A permission request follows a clear user action.','Product opt-out blocks future sends despite a browser grant.','Denied devices retain an authorized in-app inbox.'], mistakes=['Treating a browser grant as consent to every alert.', 'Requesting permission during first-page load.', 'Removing the in-app path when permission is denied.'], related=['web-tech/permission-request-timing-and-manual-fallback','web-tech/preference-change-propagation-and-audit','web-tech/live-update-reconnect-and-order']),
    dict(path='web-tech/push-subscription-account-binding-and-rotation', title='Push Subscription Account Binding and Rotation', summary='Bind each endpoint to a verified account and device lifecycle without exposing it as a public identifier.',
    definition='A push subscription contains an endpoint and encryption material for one service-worker registration. The endpoint is a delivery capability and should be handled as a secret, not logged in a page URL or treated as a public user ID. The browser sends subscription data to the application server after a signed-in, protected registration request. The server binds it to the current actor, tenant, device record, and enabled alert category. Subscriptions can expire or change, and a device can switch accounts. Rotation, logout, revocation, and invalid endpoint responses need defined cleanup paths.',
    case='Reviewer 29 enables urgent alerts on a shared tablet while signed into organization 6. Later reviewer 62 signs in on the same browser. If the server associates the old endpoint with both accounts, reviewer 62 may see a lock-screen alert about reviewer 29’s case 47. The app unbinds or deactivates the old account’s subscription during sign-out and requires a new authorized registration for reviewer 62. A stale endpoint returned by the push service is removed rather than retried forever. A subscription-change event may help repair state, but account binding remains a server-owned check.',
    implementation='Create a server endpoint that accepts the browser subscription only under authenticated actor and tenant context. Protect the write against cross-site request forgery and validate the endpoint shape and encryption-key fields without trusting client-supplied user or tenant IDs. Store the subscription encrypted or otherwise protected under the product threat model, and limit staff access to it. Keep one stable device record or subscription fingerprint for idempotent updates while avoiding full endpoint values in ordinary logs. On account switch, logout, permission loss, or push-service invalidation, mark the old binding inactive. Rotate application-server signing keys deliberately and plan how existing subscriptions will be renewed.',
    cost='A subscription lookup by account and device should be O(1) with suitable indexes, while sending to d devices costs at least O(d) delivery attempts. Keeping stale endpoints wastes storage and push-service requests. Key rotation can create a burst of resubscriptions and failed deliveries, so measure active and invalid endpoint counts. A subscription endpoint has high sensitivity even though it is not a password; limit retention and audit access. Device cleanup is extra work, but it prevents account crossover on shared browsers.',
    failure='A client POST contains userId 29 and tenantId 6, and the server trusts those fields while saving the endpoint. A signed-in user can bind a different account to a device. Derive identity from the verified session and reject forged scope. Another failure logs the entire subscription in a request trace; a copied endpoint can be misused for delivery. Redact the capability. Test repeated registration, shared-device account switch, role removal, invalid endpoint response, and a subscription that changes while a tab is closed.',
    drill='Register a subscription for reviewer 29 and organization 6. Repeat the same request, then forge reviewer 62 and tenant 9 fields; verify the server retains only trusted identity and does not duplicate the device record. Sign out and in as reviewer 62, send an alert for case 47, and confirm the old binding is ineligible. Simulate endpoint expiry and application-server key rotation. Inspect logs for endpoint and encryption material leakage.',
    decision='Bind subscription capabilities to current server-trusted identity and retire them when device, permission, or account state changes.',
    code='function subscriptionOwnerMatches(actor, binding) {\n  return actor.userId === binding.userId && actor.tenantId === binding.tenantId && binding.active;\n}\nconsole.log(subscriptionOwnerMatches({ userId: 62, tenantId: 9 }, { userId: 29, tenantId: 6, active: true }));\n// Output: false',
    checks=['A forged account field cannot change a subscription owner.','Shared-browser account switching disables the old binding.','Logs and public URLs contain no subscription endpoint.'], mistakes=['Using a client user ID as authority for subscription ownership.','Logging the full endpoint as a harmless URL.','Retrying invalid endpoints indefinitely.'], related=['web-tech/session-cookie-and-csrf-boundary','web-tech/permission-revocation-and-active-sessions','web-tech/browser-storage-cleanup-on-account-change']),
    dict(path='web-tech/private-notification-payload-and-click-routing', title='Private Notification Payload and Click Routing', summary='Keep lock-screen text minimal and reauthorize the destination when a notification is opened.',
    definition='A push payload may reach a device outside the app’s visible page, and a system notification may appear on a lock screen. Transport encryption protects a message in transit but does not make its displayed text private from nearby people. Put only the minimum information needed for the alert in title and body. A notification click is navigation intent, not an authorization grant. The destination must load current server state under the current signed-in account; if access changed, show the normal denied or sign-in route without exposing a case title or note.',
    case='An urgent assignment arrives for case 47. A detailed alert reading Damaged valve at named residence, assigned to reviewer 29 would reveal private facts on a shared tablet. The product instead displays New urgent assignment and an action to Open assignments. When clicked, the service worker focuses an existing authorized client or opens a safe application route. The page asks the server for the current assignment list. If reviewer 29 has signed out or lost the case, the route does not display the old details. The notification itself does not carry a signed download link.',
    implementation='Define a small allowlisted payload schema with a category, opaque notification ID, and safe route class. Reject arbitrary title, body, URL, and case-note fields from job producers. The service worker shows a user-visible notification and handles click through a vetted same-origin route; validate any stored path before opening it. Use notification tags or grouping carefully so one alert does not silently replace an unrelated urgent item. Fetch private detail only after the app is active and authenticated. Account changes should close or ignore stale notifications where the platform permits, but the server check remains the final boundary.',
    cost='A small payload lowers transfer and exposure; delivering n alerts still costs O(n) send attempts and can burden attention. Fetching details after click adds a network round trip, but ensures current authorization and content. Grouping can reduce notification count, yet over-grouping can hide separate urgent cases. Measure stale-click denials, lock-screen content review findings, notification count per shift, and whether reviewers reach the relevant inbox. Do not use click-through rate as proof that a confidential message was delivered safely.',
    failure='A worker builds notification text from the raw case title, which includes a private person’s name. The server encrypts the payload, but the operating system displays that name on the lock screen. Move to an allowlisted generic message. Another click handler trusts a URL from the payload and opens an arbitrary destination. Restrict route classes and reauthorize on the destination. Test sign-out between send and click, a case reassignment, multiple accounts on one browser, and a stale notification after an export or deletion operation.',
    drill='Prepare an urgent case with a private title and note, then inspect the exact push payload and visible lock-screen text. Verify neither contains the private fields. Click while signed in, after sign-out, and after role revocation; each path should reach a current server decision. Attempt to inject an external URL and an unknown payload key, and verify the producer rejects both. Send two urgent items with the same tag and inspect whether the grouping rule preserves their meaning.',
    decision='Make the alert safe to display in public and treat clicks as untrusted routes back to current authorized state.',
    code='function safeAlertPayload(event) {\n  if (event.kind !== "urgent_assignment") throw new Error("unsupported alert");\n  return { kind: event.kind, title: "New urgent assignment", route: "/assignments" };\n}\nconsole.log(JSON.stringify(safeAlertPayload({ kind: "urgent_assignment", caseTitle: "Private case 47" })));\n// Output: {"kind":"urgent_assignment","title":"New urgent assignment","route":"/assignments"}',
    checks=['No private case field appears in payload or visible notification text.','Notification clicks lead to current server authorization.','Unapproved destinations and payload fields are rejected.'], mistakes=['Confusing transport encryption with lock-screen privacy.','Using a notification click as access permission.','Accepting an arbitrary destination URL from a job payload.'], related=['web-tech/object-level-authorization-for-reads-and-writes','web-tech/browser-security-and-data-stewardship','web-tech/route-scroll-and-focus-restoration']),
    dict(path='web-tech/push-delivery-retries-expiry-and-inbox-fallback', title='Push Delivery Retries, Expiry, and Inbox Fallback', summary='Model accepted sends separately from device display and keep an authorized durable inbox.',
    definition='A successful request to a push service means it accepted a delivery attempt, not that a device displayed the notification or that a person read it. Devices can be offline, subscriptions can expire, services can reject a request, and alerts can become irrelevant before delivery. Give each alert an event identity, expiry deadline, current preference check, and deduplication rule. The application inbox holds the durable assignment. Push is a timely signal pointing to that state, not the only record of work. Delivery telemetry should distinguish queued, accepted, rejected, expired, and opened states without inventing a guaranteed delivered state.',
    case='Case 47 is assigned to reviewer 29 at 09:17. An urgent alert is queued, but the reviewer’s phone is offline. At 09:26 the case is reassigned to reviewer 62. Sending the old alert at 09:31 would create confusion and could reveal that reviewer 29 previously held a private assignment. The worker checks current assignment, alert expiry, and preference before each attempt and cancels the stale item. The inbox reflects current ownership. Reviewer 62 can see the new assignment after sign-in even if push delivery fails. A duplicate worker execution must not create two distinct alerts for the same assignment event.',
    implementation='Write an outbox record with an immutable alert ID, recipient scope, purpose, creation time, and expiry. Before sending, recheck current authorization, category preference, and whether the event is superseded. Use a bounded retry policy for transient push-service failures and retire a subscription on a definitive invalid-endpoint response. Apply a reasonable time-to-live so a stale urgent alert does not appear days late. Deduplicate by event identity at the application layer; a network retry can still produce uncertain outcomes, so notifications should be idempotent from the user’s perspective. Keep the inbox query independent of push subscription state.',
    cost='Sending to d active devices is O(d) attempted requests per alert. Retries multiply that work and can create queue pressure during a push-service outage, so use backoff and a deadline rather than unbounded replay. Durable inbox storage grows with assignment volume and retention policy, but it supports a reliable audit of current work. Exactly-once human display is not a realistic guarantee across push services and devices. Measure accepted sends, invalid subscriptions, expired alerts, stale cancellations, retry backlog, and inbox retrieval success instead of a fabricated delivery percentage.',
    failure='The worker retries every failure forever. After a weekend outage, obsolete alerts for cases already resolved arrive in a burst. Add expiry and a current-state check before each retry. Another dashboard marks Accepted as Delivered and concludes the person saw an alert; that status is unsupported. Rename it and distinguish an observed click if one occurs. Disable push entirely and confirm the assignment inbox still works. Test duplicate outbox processing, a lost push-service response, endpoint invalidation, role change, account switch, and a device returning online after the alert deadline.',
    drill='Queue an urgent assignment for case 47 and force one transient push failure, one invalid endpoint, and one uncertain accepted response. Reassign or resolve the case before retry and verify stale cancellation. Execute the worker twice with the same alert ID and inspect visible grouping and inbox records. Keep a device offline until after expiry, then reconnect it. Compare the user-visible inbox with delivery telemetry and avoid labeling a push-service acceptance as a confirmed read.',
    decision='Use push as an expiring, best-effort signal; the authorized inbox carries the current work and recovery path.',
    code='function alertDecision(alert, now, assignment) {\n  if (now >= alert.expiresAt) return "expired";\n  if (assignment.reviewerId !== alert.reviewerId) return "superseded";\n  return "attempt-send";\n}\nconsole.log(alertDecision({ expiresAt: 80, reviewerId: 29 }, 47, { reviewerId: 62 }));\n// Output: superseded',
    checks=['Expired or reassigned work cannot trigger a stale alert.','Duplicate processing preserves one logical alert identity.','The in-app inbox works when push fails or is disabled.'], mistakes=['Calling push-service acceptance a confirmed device display.','Retrying past the alert’s useful lifetime.','Making push the only record of an assignment.'], related=['web-tech/background-jobs-and-outbox','web-tech/offline-outbox-idempotency-and-replay','web-tech/permission-revocation-and-active-sessions']),
]

assert hub['path'] not in by_path and len(lessons) == 4
hub_entry = copy.deepcopy(by_path['web-tech/production-signals-and-incident-decisions'])
hub_entry.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL, 'aitrove:' + hub['path'])), path=hub['path'], title=hub['title'], summary=hub['summary'], sort_order=2800, created_at=stamp, updated_at=stamp, published_at=stamp)
hub_entry['data'] = {'subject_root':'web-tech/web-technology','section_path':hub['path'],'content_format':'html','seo_ready':False,'modules':[],'resource_tabs':[{'title':'Web Development','path':'web-tech/web-technology'},{'title':'Projects','path':'web-tech/web-technology/project'},{'title':'Quizzes','path':'web-tech/quizzes'}]}
entries.append(hub_entry)
by_path[hub['path']] = hub_entry

for number, topic in enumerate(lessons):
    assert topic['path'] not in by_path
    subprocess.run(['node','--check','--input-type=module'], input=topic['code'], text=True, capture_output=True, check=True)
    entry = copy.deepcopy(by_path['web-tech/trace-context-across-request-and-job'])
    entry.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL, 'aitrove:' + topic['path'])), path=topic['path'], title=topic['title'], summary=topic['summary'], sort_order=2810 + number, created_at=stamp, updated_at=stamp, published_at=stamp)
    related = [hub['path']] + [item['path'] for item in lessons if item['path'] != topic['path']] + topic['related']
    body = p(topic['definition']) + '<h2>Working case</h2>' + p(topic['case'])
    body += '<h2>Implementation boundary</h2><pre><code class="language-javascript">' + html.escape(topic['code'], quote=False) + '</code></pre>' + p(topic['implementation'])
    body += '<h2>Cost and boundaries</h2>' + p(topic['cost']) + '<h2>Failure trace</h2>' + p(topic['failure'])
    body += '<h2>Verification</h2><ul>' + ''.join('<li>' + html.escape(item) + '</li>' for item in topic['checks']) + '</ul>'
    body += '<h2>Practice drill</h2>' + p(topic['drill']) + '<h2>Decision note</h2>' + p(topic['decision'])
    body += '<h3>Common Mistakes</h3><ul>' + ''.join('<li>' + html.escape(item) + '</li>' for item in topic['mistakes']) + '</ul>'
    body += '<h2>Connected lessons</h2><p>' + '; '.join(link(item) for item in related) + '.</p>'
    entry['body'] = body
    entry['data'] = {'subject_root':'web-tech/web-technology','section_path':hub['path'],'content_format':'html','seo_ready':False,'kind':'tutorial','author_path':'authors/aitrove-editorial','reading_minutes':max(6, round(len(re.findall(r'\b\w+\b', re.sub(r'<[^>]+>', ' ', body))) / 155)), 'related':related}
    entries.append(entry)
    by_path[topic['path']] = entry

hub_entry['data']['modules'] = [{'title':hub['title'],'summary':hub['summary'],'lessons':[item['path'] for item in lessons]}]
hub_entry['body'] = p(hub['overview']) + '<h2>Topics in this track</h2><ul>' + ''.join('<li>' + link(item['path']) + ' — ' + html.escape(item['summary']) + '</li>' for item in lessons) + '</ul>'
hub_entry['body'] += '<h2>Prerequisite paths</h2><p>' + '; '.join(link(path) for path in hub['bridges']) + '.</p>'

root_entry = by_path['web-tech/web-technology']
root_entry['data']['modules'].append({'title':hub['title'],'summary':hub['summary'],'lessons':[hub['path']] + [item['path'] for item in lessons]})
root_entry['body'] += '<h2>' + link(hub['path']) + '</h2>' + p(hub['summary']) + '<ul>' + ''.join('<li>' + link(item['path']) + ' — ' + html.escape(item['summary']) + '</li>' for item in lessons) + '</ul>'
root_entry['updated_at'] = stamp
for path, targets in {
    'web-tech/browser-capabilities-and-permission-lifecycle':[hub['path'],lessons[0]['path']],
    'web-tech/media-and-live-updates':[lessons[3]['path']],
    'web-tech/permission-request-timing-and-manual-fallback':[lessons[0]['path']],
    'web-tech/permission-revocation-and-active-sessions':[lessons[1]['path'],lessons[2]['path']],
    'web-tech/background-jobs-and-outbox':[lessons[3]['path']],
    'web-tech/privacy-aware-external-integrations':[hub['path']],
}.items():
    entry = by_path[path]
    entry['body'] += '<h2>Further connections</h2><p>' + '; '.join(link(item) for item in targets) + '.</p>'
    entry['updated_at'] = stamp

fixture.write_text(json.dumps(entries, ensure_ascii=False, indent=2) + '\n')
print(json.dumps({'new_hubs':1,'new_lessons':len(lessons)}))
